(function(){const txt=s=>(s.n+" "+s.m.map(m=>m[1]).join(" ")).toLowerCase();
Object.values(KS).forEach(s=>{const t=txt(s);if(s.t==="swinger"||s.t==="elektromos"){if(/fluoresz|fluo\b|csepp|drops|csengő|csengo|hegyjelző|hegyjelzo|tip.?light|bell|karika|foszfor|csörgő|csorgo|spiccfény|spiccfeny|spiccre|világítócső|vilagitocso|bim-?bi|night ?light|csipeszes|hagyományos|hagyomanyos/.test(t)&&!/swing|lánc|dropper|bobbin|hanger|riaszt|alarm/.test(t))s.t="hagyomanyos"}});
Object.values(BT).forEach(s=>{const t=txt(s);
if(/buzz\s*-?bar/.test(t))s.t="buzzbar";
else if(/tri-?pod/.test(t))s.t="tripod";
else if(s.t==="kereszttarto"){s.t=/csalizó/.test(t)?"csalizo":/leszúró|nyél|készlet/.test(t)?"leszuro":/fej|kupak/.test(t)?"fej":"specialis"}
else if(s.t==="rodpod"&&/polc|vödör|stég/.test(t))s.t="specialis";
});})();
const KJT={elektromos:"Elektromos kapásjelzők",szett:"Elektromos kapásjelző szettek",swinger:"Swingerek",hagyomanyos:"Hagyományos kapásjelzők"};
const BTT={rodpod:"Rod podok",tripod:"Tripodok",leszuro:"Leszúrható bottartók",buzzbar:"Buzzbarok",csalizo:"Csalizó bottartók",fej:"Bottartó fejek",specialis:"Speciális bottartók, kiegészítők"};
/*KJSZ*/Object.keys(KS).forEach(k=>{const s=KS[k];if(s.t!=="elektromos")return;const sm=s.m.filter(m=>m[2]==="Szett"||/szett|\d\+\d/i.test(m[1]));if(!sm.length)return;s.m=s.m.filter(m=>!sm.includes(m));KS[k+"_szett"]={t:"szett",b:s.b,n:s.n,m:sm};if(!s.m.length)delete KS[k]});
