 let t=nk(c).replace(/pro\s+premium/g,"propremium").replace(/bull\s+dog/g,"bulldog").replace(/cast\s+master/g,"castmaster").replace(/\b\d+(?:[.,]\d+)?\s?m(?=[a-z])/g," ").replace(/\b\d+x\d+m(?=[a-z])/g," ").replace(/[^a-z0-9]+/g," ").trim().split(" ").filter(Boolean).map(w=>SYN[w]||w);
