const pfAllowed=slot=>{const m=sLoad().method;return slot!=="bot"&&m&&PFM[slot]&&PFM[slot][m]||null};
const PFB=[[0,20000,"0–20 000 Ft"],[20001,35000,"20 001–35 000 Ft"],[35001,50000,"35 001–50 000 Ft"],[50001,1e12,"50 000 Ft felett"]];
const PFCL=c=>c==="Picker"?"Finom / picker":c;
function pfAll(slot){return sItems(slot).map(x=>{let br="",cat="";
if(x.t==="bot"){br=B[BR(x.k)]||BR(x.k);cat=SE[x.k].c}
else if(x.t==="orso"){br=RS[x.k].b||"Nevis";cat=RS[x.k].u}
else{const C=catOf(x.t),s=C&&C.D[x.k];if(s){br=s.b;cat=C.S[s.t]||""}}
return{...x,br,cat}})}
function pfCount(a,f){const o={};a.forEach(x=>{const v=f(x);if(v)o[v]=(o[v]||0)+1});return o}
function pfState(slot){const meth=sLoad().method||"",key=slot+"|"+meth;if(PF.key!==key){PF.key=key;PF.all=0;PF.cat="";PF.pr="";PF.br="";PF.q=""}
let base=pfAll(slot);const al=pfAllowed(slot);if(al&&!PF.all){base=base.filter(x=>al.includes(x.cat));if(slot==="kapasjelzo"&&sLoad().method==="feeder")base=base.filter(x=>/feeder/i.test(x.n))}const cats=pfCount(base,x=>x.cat);if(PF.cat&&!cats[PF.cat])PF.cat="";
const a1=PF.cat?base.filter(x=>x.cat===PF.cat):base;
const pc=PFB.map(b=>a1.filter(x=>x.pr>=b[0]&&x.pr<=b[1]).length);
if(PF.pr!==""&&!pc[+PF.pr])PF.pr="";
const a2=PF.pr!==""?a1.filter(x=>x.pr>=PFB[+PF.pr][0]&&x.pr<=PFB[+PF.pr][1]):a1;
const brs=pfCount(a2,x=>x.br);if(PF.br&&!brs[PF.br])PF.br="";
const a3=PF.br?a2.filter(x=>x.br===PF.br):a2;
return{cats,pc,brs,a3,n1:a1.length}}
function pfUI(slot){const S=pfState(slot),chip=(k,v,l,n,on)=>`<button type="button" class="chip ${on?"on":""}" data-pf="${k}|${v}">${l}${n!=null?' <small>('+n+')</small>':""}</button>`;
let h="";const al=pfAllowed(slot);if(al)h+='<div class="sec">Módszer: '+tname(sLoad().method)+'</div><div class="chips">'+chip("all","0","Csak a módszerhez illők",null,!PF.all)+chip("all","1","Minden termék",null,!!PF.all)+'</div>'+(slot==="kapasjelzo"&&sLoad().method==="feeder"&&!PF.all?'<p class="m">Feedernél csak a kifejezetten feeder technikához készült elektromos kapásjelzők látszanak.</p>':'');const ck=Object.keys(S.cats).sort((a,b)=>S.cats[b]-S.cats[a]);
if(ck.length>1)h+='<div class="sec">Típus / felhasználás</div><div class="chips">'+chip("cat","","Mind",null,!PF.cat)+ck.map(c=>chip("cat",c,PFCL(c),S.cats[c],PF.cat===c)).join("")+'</div>';
h+='<div class="sec">Ársáv</div><div class="chips">'+chip("pr","","Mind",null,PF.pr==="")+PFB.map((b,i)=>S.pc[i]?chip("pr",String(i),b[2],S.pc[i],PF.pr===String(i)):'<span class="chip" style="opacity:.4" aria-disabled="true">'+b[2]+' (0)</span>').join("")+'</div>';
const bk=Object.keys(S.brs).sort((a,b)=>(S.brs[b]-S.brs[a])||a.localeCompare(b,"hu"));
if(bk.length>1||PF.br)h+='<div class="sec">Márka</div><div class="chips">'+chip("br","","Mind",null,!PF.br)+bk.map(b=>chip("br",b,b,S.brs[b],PF.br===b)).join("")+'</div>';
return h}
function pickRows(slot,qs){const S=pfState(slot),toks=lc(qs||"").split(/\s+/).filter(Boolean);const all=S.a3.filter(x=>{const hay=lc(x.n+" "+x.info+" "+x.br);return toks.every(t=>hay.includes(t))});
return`<p class="sub">${all.length} találat, ár szerint növekvő sorrendben${all.length>60?" (az első 60 látszik, szűkíts a szűrőkkel vagy a kereséssel)":""}</p>`+all.slice(0,60).map(x=>`<div class="row"><div><b>${x.n}</b><div class="m">${x.info} · ${x.m[5].length} bolt</div></div><div style="text-align:right"><div class="price" style="margin:0"><small>legolcsóbb </small>${ft(x.pr)}</div><button type="button" class="btn" style="margin-top:6px" data-pick="${slot}|${x.t}|${x.k}|${x.id}">Kiválasztom</button></div></div>`).join("")}
function pickerPage(slot){const d=SLOTS.find(x=>x[0]===slot),meth=sLoad().method;pfState(slot);
return`<div class="bc"><a href="#">Kezdőlap</a> › <a href="#szett">Horgász szett</a> › ${d[1]}</div><h1>${d[1]} választása</h1><p class="sub">${slot==="bot"&&meth?"Szűrve a módszerre: "+tname(meth)+". ":""}Szűrj típusra, ársávra és márkára, vagy keress névre. A márkák és ársávok mindig csak a már kiválasztott szűrőknek megfelelő termékeket mutatják.</p>${pfUI(slot)}<input id="sq" type="search" class="sq" placeholder="Szűrés névre, pl. shimano, 4000, vanity…" autocomplete="off"><div id="sres">${pickRows(slot,PF.q)}</div>`}
document.addEventListener("click",e=>{const t=e.target.closest&&e.target.closest("[data-pf]");if(!t)return;e.preventDefault();const[k,v]=t.dataset.pf.split("|");if(k==="all"){PF.all=+v;PF.cat="";PF.pr="";PF.br=""}else if(k==="cat"){PF.cat=v;PF.pr="";PF.br=""}else if(k==="pr"){PF.pr=v;PF.br=""}else PF.br=v;render()});
/*PF-END*/

function szettPage(p){if(p[1]&&SLOTS.some(x=>x[0]===p[1]))return pickerPage(p[1]);
const S=sLoad(),sl=S.slots||{},meth=S.method||"";let total=0,cnt=0;
let h='<h1>Horgász szett</h1><p class="sub">Állítsd össze a felszerelésedet kategóriánként. A szett ára a kiválasztott termékek legolcsóbb ajánlataiból jön ki.</p>';
h+='<div class="sec">Mit horgászol?</div><div class="chips" style="margin-bottom:6px">'+[["","Még nem tudom"],["feeder","Feeder"],["bojlis","Bojlis / pontyozás"],["pergeto","Pergetés"]].map(([k,n])=>`<button type="button" class="chip ${meth===k?"on":""}" data-smethod="${k}">${n}</button>`).join("")+'</div><p class="m" style="margin:0 0 14px">A módszer a bot, az orsó, a bottartó és a kapásjelző választásánál is szűr (a „Minden termék” gombbal kikapcsolható).</p>';
h+='<div class="sec">A szetted</div>';
SLOTS.forEach(([slot,nm,t])=>{const it=sl[slot],r=it?wlRes(it):null,pr=it?wlPrice(it):null;
const skip=meth==="pergeto"&&(slot==="bottarto"||slot==="kapasjelzo");if(skip)return;
if(r&&pr!=null){total+=pr;cnt++}
h+=`<div class="slot ${r?"full":""}"><div class="sic">${ic(slot)}</div><div class="sbd"><b>${nm}</b>`+(r?`<a class="nm" href="${r.h}">${r.n}</a><div class="m">${r.info} · ${r.m[5].length} bolt</div>`:`<div class="m">${skip?"Pergetéshez általában nem kell, kihagyható.":"Még nincs kiválasztva."}</div>`)+`</div><div class="sac">`+(r?`<div class="price" style="margin:0">${pr!=null?ft(pr):"nincs ár"}</div><a class="btn" href="#szett-${slot}">Csere</a><button type="button" class="btn" data-sclear="${slot}">Eltávolítás</button>`:`<a class="btn pri" href="#szett-${slot}">${nm} választása</a>`)+`</div></div>`});
h+=(meth==="pergeto"?'<p class="m" style="margin:8px 0">Pergetéshez a zsinór, a háló és további kiegészítők később kerülnek ide.</p>':'')+`<div class="stot"><div><b>Összesen</b><div class="m">${cnt} termék, a legolcsóbb ajánlatok szerint, szállítási költség nélkül</div></div><div class="price" style="margin:0;font-size:22px">${cnt?ft(total):"–"}</div></div>`;
if(cnt)h+='<div class="btnrow" style="margin-top:10px"><button type="button" class="btn" data-sall="1">♡ Mind a kívánságlistára</button><button type="button" class="btn" data-sreset="1">Szett törlése</button></div>';
h+='<div class="prem"><b>Horgász asszisztens – hamarosan</b><p class="m" style="margin:6px 0 0">Itt fog segíteni az oldal: kiválasztod a horgászmódszert és a tudásszinted (kezdő vagy haladó), és a termékek adatai alapján ajánlja, hogy milyen bothoz milyen orsó, zsinór, bottartó és egyéb felszerelés illik, így nem kell keresgélned. Ez még nem működik. Most csak magad állíthatod össze a szettet.</p></div>';
h+='<p class="note">A szett csak ebben a böngészőben tárolódik, a szerverre nem kerül fel.</p>';return h}
document.addEventListener("click",e=>{const t=e.target.closest&&e.target.closest("[data-set],[data-pick],[data-sclear],[data-smethod],[data-sall],[data-sreset]");if(!t)return;e.preventDefault();e.stopPropagation();const d=t.dataset;
if(d.set){const[tt,k,id]=d.set.split("|"),slot=slotOfT[tt];sHas(tt,k,id)?sSet(slot,null):sSet(slot,{t:tt,k,id});render()}
else if(d.pick){const[slot,tt,k,id]=d.pick.split("|");sSet(slot,{t:tt,k,id});location.hash="#szett"}
else if(d.sclear){sSet(d.sclear,null);render()}
else if(d.smethod!==undefined){const S=sLoad(),sl={...(S.slots||{})};if(d.smethod==="pergeto"){delete sl.bottarto;delete sl.kapasjelzo}sSave({...S,method:d.smethod||null,slots:sl});render()}
else if(d.sall){Object.values(sLoad().slots||{}).forEach(it=>{if(it&&!wlHas(it.t,it.k,it.id))wlToggle(it.t,it.k,it.id)});render()}
else if(d.sreset){sSave({...sLoad(),slots:{}});render()}},true);
(function(){const dr=$("drw"),mb=$("mb");const set=o=>{dr.hidden=!o;mb.setAttribute("aria-expanded",o);mb.setAttribute("aria-label",o?"Menü bezárása":"Menü megnyitása");document.body.style.overflow=o?"hidden":"";if(o)setTimeout(()=>{const a=dr.querySelector("a");a&&a.focus()},30);else mb.focus()};
mb.onclick=()=>set(dr.hidden);$("mclose").onclick=()=>set(false);$("scrim").onclick=()=>set(false);dr.addEventListener("click",e=>{if(e.target.closest("a"))set(false)});
document.addEventListener("keydown",e=>{if(e.key==="Escape"&&!dr.hidden)set(false)})})();
