const LDOR=(s)=>{const br=String(s.b||'Nevis').toLowerCase();const r=LDOFR.find(x=>x[0]===br&&x[1].test(s.n));return r?r[2]:null};
function LDREEL(k,m,full){const s=RS[k],br=s.b||"Nevis",fk=LDN(m[6]),cs=LDN(m[3]),at=LDN(m[4]),sz=LDN(m[2]||m[1]),cl=LDRS(sz);let o=[];
o.push(`A ${br} ${s.n} sorozat ${sz?sz+" méretű ":""}${fk?fk.toLowerCase()+" ":""}orsója`+(cs?`, ${cs} csapággyal`:"")+(at?`, ${at} áttétellel`:"")+".");
const bd=LDBRD(br);if(bd)o.push(bd.trim());
const orr=LDOR(s);if(orr)o.push("A gyártó oldala (delphin.sk) alapján, összefoglalva: "+orr);
o.push(`Felhasználás: ${LDRU[s.u]||String(s.u).toLowerCase()}.`);
if(fk==="Elsőfékes")o.push("Az elsőfékes (frontfékes) orsó fékje az orsó elején van, egyenletesen, finoman állítható, ezért feeder-, match- és általános horgászathoz is népszerű.");
else if(fk==="Nyeletőfékes")o.push("A nyeletőfékes (baitrunner) orsó a hátsó fék mellett szabadonfutó funkciót ad, így a pontyozásban, harcsázásban a halak elengedhetők, és nem húzzák le a botot.");
if(cl)o.push(LDRSZ[cl]);
o.push(LDFT);return o.join(" ")}
function LDREELSER(k){const s=RS[k],br=s.b||"Nevis",ms=s.m,fk=[...new Set(ms.map(m=>LDN(m[6])).filter(Boolean))],sz=ms.map(m=>LDN(m[2]||m[1])).filter(Boolean);
return `${br} ${s.n}: ${ms.length} méret`+(sz.length?` (${sz.slice(0,5).join(", ")}${sz.length>5?" …":""})`:"")+(fk.length?`, ${fk.join(" / ").toLowerCase()}`:"")+". "+LDBRD(br)+(LDOR(s)?"A gyártó oldala (delphin.sk) alapján: "+LDOR(s)+" ":"")+`Felhasználás: ${LDRU[s.u]||String(s.u).toLowerCase()}. `+LDFT}
const LDCT={"szett":"Az elektromos kapásjelző szett általában 2–4 kapásjelzőt és egy vevőegységet (receivert) tartalmaz, így egy csomagban megkapod a teljes jelzőrendszert, gyakran tokkal együtt; a darabár általában kedvezőbb, mint ha külön vennéd meg őket.","elektromos":"Az elektromos kapásjelző hang- és fényjelzéssel jelzi a kapást, a legtöbb típus hangerő-, érzékenység- és hangszínállítással, éjszakai horgászathoz is.","swinger":"A swinger vagy kapásjelző a zsinórra akasztott, mozgó test, amely a zsinór mozgását szemmel követhetően mutatja, és a kapásjelzővel együtt használható.","hagyomanyos":"A hagyományos kapásjelző egyszerű, elem nélküli, kis méretű jelző (például fluoreszkáló vagy világító csepp, úszószerű jelző, csengő), amit a zsinórra vagy a bot hegyére tesznek: a kapást a mozgása vagy a hangja jelzi.","buzzbar":"A buzzbar (kereszttartó) a két bottartó fejet és a kapásjelzőket egy közös rúdon tartja, így a botok és a jelzők távolsága rögzített és rendezett; pontyozásnál rodpodon vagy két leszúrón használatos.","rodpod":"A rod pod önálló, szétszedhető bottartó állvány, amely nem igényel leszúrást, ezért kemény, köves vagy kikövezett partszakaszon is használható.","tripod":"A tripod három lábú állvány, amely könnyebb, gyorsabban felállítható, és több botnál is stabil alátámasztást ad.","leszuro":"A leszúrható bottartó a talajba szúrható, egyszerű, olcsó és gyors megoldás kisebb horgászathoz.","csalizo":"A csalizó bottartó a bot kényelmes, stabil felfektetését és a csalizást segíti.","kereszttarto":"A kereszttartó a bottartó és a kapásjelző stabil, vízszintes elhelyezését biztosítja.","fej":"A bottartó fej a bot biztos rögzítésére szolgál, az állvány vagy a leszúró részeként is használható.","specialis":"A speciális bottartó egyedi helyzetekre (például csónak, part, több bot) készült megoldás."};
const LDOFC=[
["kj",/^Tex1/i,"Vízálló, ABS házas pontyozó kapásjelző. Három tárcsán állítható a hangerő (hat fokozat, némával), a hangszín (öt) és az érzékenység (öt fokozat). Három AAA elemmel működik, nappali, éjszakai és kikapcsolt üzemmódja van, snag gear, rögzítőanya és 2,5 mm-es csatlakozó külső jelzőhöz tartozik."],
["kj",/^Ixton/i,"Vízálló, különálló pontyozó kapásjelző, ami fénnyel és hanggal jelez bármilyen időben. Nyolc hangszín, nyolc hangerőfokozat (némával), öt érzékenységi szint, a beállításokat megjegyzi. Két AAA elemmel működik, gyenge elemnél villog, háttérvilágított bobbin, kapás utáni jelzőfény és levehető snag gear tartozik hozzá."],
["kj",/^Minx/i,"Kompakt, vízálló, egyszerűen kezelhető kapásjelző egyetlen hosszú élettartamú 23A 12 V-os elemmel. Öt hangerőfokozat (némával), a LED kapás után 10 másodpercig világít, a beállításokat kikapcsolás után is megjegyzi; kék és piros színben."],
["kj",/^Fx1/i,"Vízálló, fekete ABS házas kapásjelző fény- és hangjelzéssel, nappal-éjszaka kapcsolóval, ami éjszakára bekapcsolja a pozíciófényt. Hangszín és érzékenység öt-öt fokozatban állítható, külön hangjelzés a visszafutó kapáshoz, hét LED szín és öt hangerőfokozat (némával). 9 V-os elemmel működik, gyenge elemnél röviden sípol; snag gear, védőburkolat és szállítótok tartozik hozzá."],
["kj",/^Dx1/i,"Kompakt, vízálló kapásjelző egy 12 V-os LR23A elemmel (gyenge elemnél röviden sípol). Öt hangerőfokozat (némával), öt hangszín, öt érzékenységi szint és hét LED szín, a beállításokat megjegyzi. A visszafutó kapást eltérő hanggal jelzi, a memóriafény kapás után kb. 15 másodpercig világít, külső jelzőt is támogat, éjszakai pozíciófénye van."],
["kj",/^Hades/i,"Olcsó elektronikus kapásjelző alap fény- és hangjelzéssel, egy LED-del, ami mindkét irányú kapást érzékel. A felső tárcsa a hangerőt állítja és záró be/ki kapcsoló is, az alsó a hangmagasságot; érzékenységállítás nincs említve. Vízálló, egy 9 V-os elemmel működik, 2,5 mm-es aljzatot kap külön függő jelzőhöz."],
["kj",/^Shocker/i,"Rezgésalapú kapásjelző, ami gumipánttal rögzül a botra, a hátoldala követi a bot formáját. Három LR44 elemmel működik, a fény kapás után 20 másodpercig villog, négy hangszín, négy hangerőfokozat és néma mód; érzékenységállítást nem említ."],
["kj",/^Iton/i,"Különálló kapásjelző minimalista kivitelben, alumínium hangszóró-fedéllel és gumírozott műanyag részekkel. Három AAA elemmel működik, sötétben is használható karos kapcsoló, jó vízállóság és hosszú elemélet. Nyolc hangszín, nyolc hangerőfokozat (némával), öt érzékenységi szint, a beállításokat megjegyzi; csengőfény, snag gear rögzítők, gyenge elem jelzés, 2,5 mm-es aljzat, és mágnes, ami bottartóra szerelve megakadályozza a téves riasztást."],
["kj",/^Wamp/i,"Elektronikus kapásjelző tartós ABS műanyagból, állítható gumipánttal rögzül a bot blankjára, a zsinór a kerekeken fut át, így a halk kapást is érzékeli. Egy gomb nyomva tartása be-/kikapcsol, rövid nyomás a hangerőt (némával), egy másik gomb a hangszínt állítja. Kapáskor hangjelzés szól és egy piros LED legfeljebb 20 másodpercig világít; három LR44 elemmel működik (nincs a csomagban), kb. 35,5 g."],
["kj",/^Runer/i,"Strapabíró, gumírozott kapásjelző fény- és hangjelzéssel normál és visszafutó kapáshoz, magas érzékenységgel és éjszakai móddal pozíció LED-del. Az alján lévő karos kapcsoló be-/kikapcsol és nappal-éjszaka módot választ; 9 V-os elemmel működik (nincs a csomagban), világító Snag Gearhez is csatlakoztatható. Állítható hangerőt és hangszínt az oldal nem említ."],
["kj",/^Easy/i,"Egyszerű, megbízható kapásjelző, ami rugalmas gumipánttal csíptethető a botra, és az alsó kapcsolóval automatikusan bekapcsol. Kapáskor a zsinór forgatja az érzékelő kereket, és hang- és fényjelzést ad. Három LR44 elemmel működik; pontyozásra és ragadozóhalászatra (csuka, angolna) ajánlott."],
["kj",/^Memory/i,"Különálló kapásjelző az Optimo szettből ihletve: a memóriafunkció kikapcsolás és elemcsere után is megőrzi a beállításokat. Állítható érzékenység, hangerő és hangszín, nappali és éjszakai mód (utóbbi pozíciófénnyel), kb. 20 másodpercre elnémítható a beállítás idejére. 9 V-os elemmel működik, levehető snag gear és bemenet világító jelzők táplálásához; gyantával lezárt áramkör a nagy esőhöz."],
["bt",/^RPX 4/i,"Könnyű alumínium rod pod matt fekete kivitelben, megerősített láb-váz csatlakozással, ami kb. 15%-kal merevebb az elődjénél. Az alapkészlet három botot tart, a négybotos kereszttartó külön kapható; a lábhossz 84–138 cm közt állítható, a magasság 60–140 cm hosszabb lábakkal (a szokásos lábakkal kb. 80 cm-ig). 90×20×7 cm-es vízálló tokban szállítható."],
["bt",/^RPX Stalk/i,"Kompakt, kétbotos alumínium rodpod homokfúvott, oxidált matt fekete felülettel és stabil láb-váz csatlakozással. Magassága 36–66 cm, lábhossza 50–75 cm között állítható, a lábak három szögben állíthatók; 50×15×7 cm-es vízálló tokban szállítható, 1,6 kg. Stalkerezéshez és hagyományos botokhoz, főleg angol stílusú, könnyű, hordozható összeállítást kedvelőknek."],
["bt",/^RPX ProMAX/i,"Teljesen fém, háromrészes rodpod eloxált, matt fekete alumínium kerettel és megerősített lábcsatlakozással. A kihúzható elülső és hátsó karok, a teleszkópos lábak és az állítható magasság és hossz lehetővé teszi a botok távolságának és szögének beállítását; 90×20×7 cm-es tokban hajtható össze, kb. 2,6 kg. Folyóra vagy nagy tóra, ahol a bothegyeket magasan kell tartani, hogy a sodrás kevésbé terhelje a zsinórt."],
["bt",/^Bronx 2G$/i,"Háromboto rodpod alumínium profilokból, tartós ABS műanyag csatlakozókkal, kb. 1,185 kg. A magasság 31–67 cm, a hossz 82–132 cm közt állítható, az 50 cm-es kereszttartó kb. 82×16×8 cm-re hajtható, a mellékelt textiltokba fér. Az eredeti BRONX továbbfejlesztése, főleg pontyozóknak, megerősített rögzítőkkel a hosszabb élettartamhoz."],
["bt",/^Craber Maxi/i,"Kompakt, fekete, könnyű rodpod alumínium profilokból ABS csatlakozókkal, ami stabil. Három botot tart, a magasság (41–85 cm) és a teleszkópos lábak (80–130 cm, három lábszög) a helyszínhez állíthatók; 80×20×6 cm-re pakolható, textiltok tartozik hozzá. Kis, benőtt vizekre és nagy, nyílt partokra is jó."],
["bt",/^BBQ/i,"Hordozható botállvány alumínium vázzal és erős ABS csatlakozókkal, a lábak a tengelyük mentén csúsztathatók az egyenetlen talajhoz. Három botot tart, magassága 56–96 cm, hossza 74–120 cm, 2,5 kg; habbal bélelt 75×30×6 cm-es táskába pakolható, stabil, alkalmazkodó botelhelyezéshez."],
];
const LDOC=(C,s)=>{if(s.b!=='Delphin')return null;const r=LDOFC.find(x=>x[0]===C.w&&x[1].test(s.n));return r?r[2]:null};
function LDCAT(C,k,m,full){const s=C.D[k],t=s.t,nm=C.name(s),lab=C.S[t]||C.nav;let o=[];
o.push(`A ${nm} ${m[1]} (${lab.toLowerCase()})`+(LDN(m[3])?`, ${C.f3.toLowerCase()}: ${m[3]}`:"")+(LDN(m[4])?`, ${C.f4.toLowerCase()}: ${m[4]}`:"")+".");
const bd=LDBRD(s.b);if(bd)o.push(bd.trim());
const oc=LDOC(C,s);if(oc)o.push("A gyártó oldala (delphin.sk) alapján, összefoglalva: "+oc);o.push(LDCT[t]||"");if(s.zd)o.push(s.zd);if(s.ed)o.push("Az importőr (Energofish) leírása szerint: "+s.ed);o.push(LDFT);return o.filter(Boolean).join(" ")}
Object.entries(SE).forEach(([k,s])=>{s.ds=s.d;try{s.d=LDRODSER(k,s)}catch(e){}});
/*LD-END*/

/*BAND-BEGIN*/
const BND0=[[0,20000,"0–20 000 Ft"],[20001,35000,"20 001–35 000 Ft"],[35001,50000,"35 001–50 000 Ft"],[50001,1e12,"50 000 Ft felett"]],BNDZ=[[0,3000,"0–3000 Ft"],[3001,5000,"3001–5000 Ft"],[5001,10000,"5001–10 000 Ft"],[10001,1e12,"10 000 Ft felett"]];let BND=BND0;
const bandIdx=()=>BND.findIndex(b=>F.min===(b[0]||0)&&F.max===(b[1]===1e12?0:b[1]));
function bandCounts(fn){const a=F.min,b=F.max;F.min=0;F.max=0;let ps=[];try{ps=fn()}catch(e){}F.min=a;F.max=b;return BND.map(x=>ps.filter(p=>p>=x[0]&&p<=x[1]).length)}
function bandUI(fn){const c=bandCounts(fn),cur=bandIdx();
return'<div class="sec">Ársáv: mennyit szánsz rá?</div><div class="chips"><button type="button" class="chip '+((!F.min&&!F.max)?"on":"")+'" data-band="-1">Mindegy</button>'+BND.map((b,i)=>c[i]?'<button type="button" class="chip '+(cur===i?"on":"")+'" data-band="'+i+'">'+b[2]+' <small>('+c[i]+')</small></button>':'<span class="chip" style="opacity:.4" aria-disabled="true">'+b[2]+' (0)</span>').join("")+'</div>'}
function bandNote(){const i=bandIdx();return i>=0?'<div class="chips" style="margin:6px 0"><button type="button" class="chip on" data-band="-1" title="Ársáv törlése">Ársáv: '+BND[i][2]+' ✕</button></div>':""}
document.addEventListener("click",e=>{const t=e.target.closest&&e.target.closest("[data-band]");if(!t)return;e.preventDefault();const i=+t.dataset.band;if(i<0){F.min=0;F.max=0}else{F.min=BND[i][0]||0;F.max=BND[i][1]===1e12?0:BND[i][1]}render()});
/*BAND-END*/

function filters(rr){let q="";const mm=/^#orso-([a-z]+)/.exec(location.hash);if(rr&&mm&&RT[mm[1]]){q='<div class="fg"><b>Fék típusa</b><div class="chips">'+["Elsőfékes","Nyeletőfékes"].map(c=>`<span class="chip ${F.cat.has(c)?"on":""}" data-s="cat" data-v="${c}">${c}</span>`).join("")+(mm[1]==="pontyozo"?`<span class="chip ${F.td?"on":""}" data-td="1">Távdobó</span>`:"")+"</div></div>"}return bandNote()+q+filtersOld(rr)}
document.addEventListener("click",e=>{const t=e.target.closest&&e.target.closest("[data-td]");if(!t)return;e.preventDefault();F.td=!F.td;render()});
const SIMW=cp=>cp<=10000?[0,.5]:cp<=30000?[.3,.3]:[.2,.2];
const simIn=(p,cp)=>{const[d,u]=SIMW(cp);return p<cp?(d>0&&p>=cp*(1-d)&&p<=cp*.95):(p>cp&&p<=cp*(1+u)&&p>=cp*1.05)};
function simBox(pool,cp,head,rowf){const mx=k=>Math.max(1,...pool.map(x=>x[k]||0)),M={no:mx("no"),dl:mx("dl"),im:mx("im")};
pool.forEach(x=>{x.s=3*(x.no||0)/M.no+2*(x.dl||0)/M.dl+1*(x.im||0)/M.im});
const d=SIMW(cp)[0],best=(a,n)=>a.sort((p,q)=>q.s-p.s||Math.abs(p.p-cp)-Math.abs(q.p-cp)).slice(0,n).sort((p,q)=>p.p-q.p);
const lo=d>0?best(pool.filter(x=>x.p<cp),2):[],hi=best(pool.filter(x=>x.p>cp),d>0?2:4);
const win=cp<=10000?"legfeljebb 50%-kal drágább":cp<=30000?"±30%":"±20%";
return`<h2>Hasonló termékek hasonló áron</h2><p class="m">${head} · ársáv: ${win} · előnyben a több boltban kapható, részletesebben leírt termék · legolcsóbb ajánlat alapján, a beállított szűrőknek megfelelően</p>`+(lo.length||hi.length?lo.map(x=>rowf(x,"dn")).join("")+hi.map(x=>rowf(x,"up")).join(""):'<p class="sub">Ebben a kategóriában nincs másik termék a hasonló ársávban.</p>')}
function simRods(k,m){const s=SE[k],cp=minP(m);if(!cp)return"";const pool=[];
Object.entries(SE).forEach(([k2,s2])=>{if((s2.t||"feeder")!==(s.t||"feeder")||s2.c!==s.c||BR(k2)!==BR(k))return;s2.m.forEach(m2=>{if(k2===k&&m2[0]===m[0])return;const p2=minP(m2);if(p2&&p2!==cp&&simIn(p2,cp)&&Math.abs(m2[2]-m[2])<=.31&&(!F.len.size||F.len.has(m2[2]))&&(!F.cat.size||F.cat.has(s2.c)))pool.push({k:k2,m:m2,p:p2,no:offsOf(m2).length,dl:LDRODDESC(k2,m2).length,im:0})})});
const lab=s.t==="bojlis"?"teszgörbe":"dobósúly",row=(x,c)=>`<a class="row sim ${c}" href="#bot-${tp(x.k)}-${BR(x.k)}-${x.k}-${x.m[0]}"><div><b>${slabel(x.k,x.m)}</b><div class="m">${String(x.m[2]).replace(".",",")} m · ${lab}: ${x.m[3]}</div></div><div class="price" style="margin:0"><small>${c==="dn"?"▼ olcsóbb · ":"▲ drágább · "}</small>${ft(x.p)}</div></a>`;
return simBox(pool,cp,`${B[BR(k)]} · ${s.c}`,row)}
const simRow=(x,c,sub)=>`<a class="row sim ${c}" href="${x.h}"><div><b>${x.n}</b><div class="m">${sub}</div></div><div class="price" style="margin:0"><small>${c==="dn"?"▼ olcsóbb · ":"▲ drágább · "}</small>${ft(x.p)}</div></a>`;
function simReels(t,k,m){const s=RS[k],cp=minP(m);if(!cp)return"";const pool=[];
Object.entries(RS).forEach(([k2,s2])=>{if(rbk(s2)!==rbk(s))return;s2.m.forEach(m2=>{if(k2===k&&m2[0]===m[0])return;if(!RT[t][1](s2,m2))return;const p2=minP(m2);if(p2&&p2!==cp&&simIn(p2,cp)&&(!F.len.size||F.len.has(m2[2]))&&(!F.cat.size||F.cat.has(m2[6])))pool.push({p:p2,m:m2,no:offsOf(m2).length,dl:LDREEL(k2,m2).length,im:0,n:`${s2.b||"Nevis"} ${s2.n} ${m2[1]}`,h:rlink(k2,m2)})})});
return simBox(pool,cp,`${s.b||"Nevis"} · ${RT[t][0]}`,(x,c)=>simRow(x,c,`méret ${sz(x.m)} · ${x.m[6]} · áttétel: ${x.m[4]}`))}
function simCat(C,t,k,m){const s=C.D[k],cp=minP(m);if(!cp)return"";const pool=[];
Object.entries(C.D).forEach(([k2,s2])=>{if(s2.t!==s.t||s2.b!==s.b)return;s2.m.forEach(m2=>{if(k2===k&&m2[0]===m[0])return;const p2=minP(m2);if(p2&&p2!==cp&&simIn(p2,cp))pool.push({p:p2,m:m2,no:offsOf(m2).length,dl:LDCAT(C,k2,m2).length,im:0,n:`${C.name(s2)} ${m2[1]}`,h:C.url(k2,m2)})})});
return simBox(pool,cp,`${s.b==="Márka nélkül"?"Márka nélkül":s.b} · ${C.S[s.t]||s.t}`,(x,c)=>simRow(x,c,`${C.f3.toLowerCase()}: ${x.m[3]} · ${C.f4.toLowerCase()}: ${x.m[4]}`))}
